import { watchDom } from '../../core/observer';
import { create } from '../../utils/dom';
import { runIconEngine } from '../../utils/icons';
import { startPtvIconEngine } from '../icons';

const REQUEST_URL = 'https://request.piggietv.com';

function isHomeRoute() {
    const hash = window.location.hash || '';

    return hash === '#/home'
        || hash === '#/home.html'
        || hash.startsWith('#/home?')
        || hash.startsWith('#/home.html?');
}

function ensureHomeTabs(header) {
    const tabsContainer = header?.querySelector('.headerTabs');

    if (!tabsContainer) return;

    if (!isHomeRoute()) {
        const fallbackTabs = tabsContainer.querySelector('.ptv-home-tabs');

        if (fallbackTabs) {
            tabsContainer.innerHTML = '';
            tabsContainer.classList.add('hide');
        }

        return;
    }

    const hasUsableTabs = tabsContainer.querySelector('.tabs-viewmenubar .emby-tab-button');
    const hasRequestTab = tabsContainer.textContent?.includes('Request');

    if (hasUsableTabs && hasRequestTab) {
        tabsContainer.classList.remove('hide');
        return;
    }

    tabsContainer.innerHTML = `
        <div is="emby-tabs" class="tabs-viewmenubar ptv-home-tabs">
            <div class="emby-tabs-slider" style="white-space:nowrap;">
                <a href="#/home" is="emby-linkbutton" class="emby-tab-button emby-tab-button-active" data-index="0">
                    <div class="emby-button-foreground">Home</div>
                </a>
                <a href="#/home?tab=1" is="emby-linkbutton" class="emby-tab-button" data-index="1">
                    <div class="emby-button-foreground">Favorites</div>
                </a>
                <a href="${REQUEST_URL}" is="emby-linkbutton" class="emby-tab-button" target="_blank" rel="noopener noreferrer" data-index="2">
                    <div class="emby-button-foreground">Request</div>
                </a>
            </div>
        </div>
    `;
    tabsContainer.classList.remove('hide');
    document.body.classList.add('withSectionTabs');

    window.CustomElements?.upgradeSubtree?.(tabsContainer);
}

function enhanceHeaderIcons() {
    const header = document.querySelector('.ptv-legacy-skinHeader, .skinHeader');
    const headerLeft = header?.querySelector('.headerLeft');

    if (headerLeft) {
        const logos = Array.from(headerLeft.querySelectorAll('.ptv-header-logo'));
        const [logo, ...extraLogos] = logos;
        extraLogos.forEach((extraLogo) => {
            extraLogo.remove();
        });

        if (!logo) {
            const headerLogo = create('a', {
                className: 'ptv-header-logo itemAction',
                attrs: {
                    href: '#/home',
                    'data-action': 'link',
                    'aria-label': 'Go to home'
                }
            });

            headerLogo.appendChild(create('img', {
                attrs: {
                    src: '/assets/logo/banner-light.png',
                    alt: 'PiggieTV',
                    loading: 'eager',
                    decoding: 'async'
                }
            }));
            headerLeft.appendChild(headerLogo);
        } else {
            logo.setAttribute('class', 'ptv-header-logo itemAction');
            logo.setAttribute('href', '#/home');
            logo.setAttribute('data-action', 'link');
            logo.setAttribute('aria-label', 'Go to home');
        }

        headerLeft.querySelectorAll('.ptv-stock-header-logo').forEach((extraLogo) => {
            extraLogo.remove();
        });
        headerLeft.querySelectorAll('.ptv-header-logo img + img').forEach((extraLogo) => {
            extraLogo.remove();
        });
    }

    if (!header) return;

    ensureHomeTabs(header);

    header
        .querySelectorAll('button, .headerButton')
        .forEach(button => {
            button.classList.add('ptv-header-stock-button');
        });

    runIconEngine(header);
}

watchDom(enhanceHeaderIcons);
window.addEventListener('hashchange', enhanceHeaderIcons);
window.addEventListener('popstate', enhanceHeaderIcons);
startPtvIconEngine();
enhanceHeaderIcons();
